/bin/bash -lc "node --input-type=module <<'JS'
const url = 'http://localhost:3000/'
const initial = await (await fetch(url)).text()
const field = initial.match(/name=\"(\\"'$ACTION_ID_[''^"]+)"/)?.[1]
if (!field) throw new Error('"'Server Action form field missing')
let cookie = ''
for (const expected of ['true', 'false']) {
  const form = new FormData()
  form.append(field, '')
  const response = await fetch(url, { method: 'POST', body: form, headers: cookie ? { Cookie: cookie } : {}, redirect: 'manual' })
  const setCookie = response.headers.get('set-cookie')
  if (response.status "'!== 200 || response.headers.has('"'location') || "'!setCookie?.includes('"'notifications-enabled=' + expected)) {
    throw new Error('Unexpected toggle response for ' + expected)
  }
  cookie = setCookie.split(';')[0]
  const html = await (await fetch(url, { headers: { Cookie: cookie } })).text()
  const state = expected === 'true' ? 'on' : 'off'
  if ("'!html.includes('"'Notifications are <"'!-- -->'"' + state)) throw new Error('Rendered state mismatch: ' + state)
}
console.log('Both toggles persisted, rendered correctly, and returned without a redirect.')
JS"
